import{_ as e,o as l,c as d,a0 as a}from"./chunks/framework.CI7OaYtj.js";const x=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),i={name:"guide/introduction.md"};function n(r,t,o,s,c,g){return l(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><p><code>unibestX</code> 是一套面向 <strong>uni-app X</strong> 的现代开发模板，目标是把原生渲染、工程规范、业务基础设施和 AI 协作能力组合成可直接开工的项目底座。</p><blockquote><p>一套代码运行到 Android、iOS、鸿蒙、H5、微信小程序与支付宝小程序。</p></blockquote><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">类别</th><th style="text-align:left;">技术</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">框架</td><td style="text-align:left;">uni-app X</td><td style="text-align:left;">原生渲染，默认 Vapor，兼容 VDOM</td></tr><tr><td style="text-align:left;">语言</td><td style="text-align:left;">UTS</td><td style="text-align:left;">编译为 Kotlin / Swift / ArkTS / JS</td></tr><tr><td style="text-align:left;">UI 框架</td><td style="text-align:left;">Vue 3</td><td style="text-align:left;">Composition API + <code>&lt;script setup&gt;</code></td></tr><tr><td style="text-align:left;">构建</td><td style="text-align:left;">Vite 5</td><td style="text-align:left;">快速启动与热更新</td></tr><tr><td style="text-align:left;">样式</td><td style="text-align:left;">Tailwind CSS v4</td><td style="text-align:left;">原子化样式 + SCSS</td></tr><tr><td style="text-align:left;">路由</td><td style="text-align:left;"><code>route-bestX</code></td><td style="text-align:left;">对标 Vue Router 4 的路由与守卫体系</td></tr><tr><td style="text-align:left;">请求</td><td style="text-align:left;"><code>request-bestX</code></td><td style="text-align:left;">请求实例、拦截器、缓存、<code>useQuery</code> / <code>useMutation</code></td></tr><tr><td style="text-align:left;">状态</td><td style="text-align:left;">Pinia / <code>x-pinia-s</code></td><td style="text-align:left;">按运行模式自动切换实现</td></tr><tr><td style="text-align:left;">国际化</td><td style="text-align:left;"><code>lime-i18n</code></td><td style="text-align:left;">中英文语言包与运行时切换</td></tr><tr><td style="text-align:left;">列表</td><td style="text-align:left;"><code>z-paging-x</code></td><td style="text-align:left;">原生下拉刷新、分页与嵌套滚动</td></tr></tbody></table><h2 id="内置能力" tabindex="-1">内置能力 <a class="header-anchor" href="#内置能力" aria-label="Permalink to &quot;内置能力&quot;">​</a></h2><ul><li>自定义 TabBar：5 种运行模式、2 种 UI 形态、角标与中间鼓包按钮。</li><li>文件路由：自动扫描 <code>src/pages</code>、<code>src/sub</code>，通过 <code>definePage</code> 声明页面元数据。</li><li>路由守卫：登录、维护、权限编排与 TabBar 页面拦截。</li><li>请求体系：多域名实例、Token 注入、统一错误处理、上传下载与流式请求。</li><li>状态管理：Vapor、Web、小程序与 App VDOM 双实现自适应。</li><li>主题系统：<code>theme.json</code> 单源维护亮色 / 暗色配色，支持动态换肤。</li><li>工程化：ESLint、Stylelint、TypeScript、Vitest、Husky、Release 与包体积检查。</li><li>AI 原生：内置 <code>unibestX-skill</code>，约束 UTS、页面、请求、路由和 TabBar 写法。</li></ul><h2 id="支持平台" tabindex="-1">支持平台 <a class="header-anchor" href="#支持平台" aria-label="Permalink to &quot;支持平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">平台</th><th style="text-align:center;">状态</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">Android</td><td style="text-align:center;">✅</td><td style="text-align:left;">Vapor / VDOM，原生 App</td></tr><tr><td style="text-align:left;">iOS</td><td style="text-align:center;">✅</td><td style="text-align:left;">Vapor / VDOM，需 macOS + Xcode</td></tr><tr><td style="text-align:left;">HarmonyOS</td><td style="text-align:center;">✅</td><td style="text-align:left;">需 DevEco Studio</td></tr><tr><td style="text-align:left;">H5</td><td style="text-align:center;">✅</td><td style="text-align:left;">支持 Docker + Nginx 部署</td></tr><tr><td style="text-align:left;">微信小程序</td><td style="text-align:center;">✅</td><td style="text-align:left;">HBuilderX 发行</td></tr><tr><td style="text-align:left;">支付宝小程序</td><td style="text-align:center;">✅</td><td style="text-align:left;">HBuilderX 5.31+</td></tr></tbody></table><h2 id="分支说明" tabindex="-1">分支说明 <a class="header-anchor" href="#分支说明" aria-label="Permalink to &quot;分支说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">分支</th><th style="text-align:left;">定位</th></tr></thead><tbody><tr><td style="text-align:left;"><code>main</code></td><td style="text-align:left;">无内置 UI 组件库的纯净基线，原生组件 + Tailwind CSS</td></tr><tr><td style="text-align:left;"><code>uniX-rice-ui</code></td><td style="text-align:left;">集成 Rice UI，适合希望开箱即用的项目</td></tr><tr><td style="text-align:left;"><code>uniX-uview-ultra</code></td><td style="text-align:left;">集成项目深度修复版 uview-ultra</td></tr></tbody></table><p>新项目若需要长期维护和完整组件生态，优先评估 <code>uniX-rice-ui</code>；需要保持最薄底座则使用 <code>main</code>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>第一次运行项目：<a href="/unibestX/docs/guide/getting-started.html">快速开始</a></li><li>配置底部导航：<a href="/unibestX/docs/guide/tabbar.html">TabBar 专题</a></li><li>页面跳转与守卫：<a href="/unibestX/docs/guide/route.html">路由篇</a></li><li>对接服务端：<a href="/unibestX/docs/guide/request.html">请求篇</a></li><li>生成接口类型：<a href="/unibestX/docs/guide/api-generator.html">自动生成接口</a></li><li>准备上线：<a href="/unibestX/docs/guide/release.html">运行发布</a></li></ul>',14)])])}const y=e(i,[["render",n]]);export{x as __pageData,y as default};
